import { readFile, writeFile, readdir } from 'node:fs/promises';
import path from 'node:path';

const root = process.cwd();
const personId = 'https://www.norbertbanhalmi.com/about/';
const wkoRaw = 'partnerschaft-für-führungskräfte';
const wkoEncoded = 'partnerschaft-f%C3%BCr-f%C3%BChrungskr%C3%A4fte';
const homepages = ['index.html','hu/index.html','de-at/index.html'];
const personDescriptions = {
  en: 'Strategic visual partnership for leaders and organisations. Executive portraiture, brand photography and C-level event imagery designed as one coherent system that builds visual trust.',
  hu: 'Stratégiai vizuális partnerség vezetőknek és szervezeteknek. Az executive portré, a brandfotózás és a C-level eseményfotózás egyetlen koherens rendszert alkot, amely vizuális bizalmat épít.',
  de: 'Strategische visuelle Partnerschaft für Führungskräfte und Organisationen. Executive-Porträts, Brandfotografie und C-Level-Eventbilder bilden ein kohärentes System, das visuelles Vertrauen aufbaut.'
};
function langOf(rel,html){const m=html.match(/<html\b[^>]*\blang=["']([^"']+)/i);const l=(m?.[1]||'').toLowerCase();if(l.startsWith('hu')||rel.startsWith('hu/'))return'hu';if(l.startsWith('de')||rel.startsWith('de-at/'))return'de';return'en';}
function meta(html,key,attr='name'){const re=new RegExp(`<meta\\b[^>]*${attr}=["']${key.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')}["'][^>]*>`, 'i');const m=html.match(re);if(!m)return null;return m[0].match(/\bcontent=["']([^"']*)["']/i)?.[1]||null;}
function patchJsonLd(html,rel){const lang=langOf(rel,html);const description=meta(html,'description','name');const ogDescription=meta(html,'og:description','property');if(description&&ogDescription&&description!==ogDescription)throw new Error(`${rel}: meta and OG description differ before migration`);return html.replace(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi,(full,raw)=>{let data;try{data=JSON.parse(raw)}catch{return full}const nodes=Array.isArray(data?.['@graph'])?data['@graph']:[data];for(const node of nodes){if(!node||typeof node!=='object')continue;const types=Array.isArray(node['@type'])?node['@type']:[node['@type']];if(types.includes('Person')&&node['@id']===personId)node.description=personDescriptions[lang];if(description&&(types.includes('WebPage')||types.includes('CollectionPage'))){const url=node.url||'';if(url===`https://www.banhalmi.art/${rel==='index.html'?'':rel.replace(/index\.html$/,'')}`||String(node['@id']||'').includes('#webpage'))node.description=description;}}
return full.replace(raw,JSON.stringify(data));});}
const skipDirs=new Set(['.git','node_modules','dist','test-results','playwright-report','.github','tests','tools','scripts']);
const textExt=new Set(['.html','.json','.jsonld','.txt','.md','.xml']);
async function walk(dir){for(const ent of await readdir(dir,{withFileTypes:true})){if(skipDirs.has(ent.name))continue;const full=path.join(dir,ent.name);if(ent.isDirectory()){await walk(full);continue}const ext=path.extname(ent.name).toLowerCase();if(!textExt.has(ext))continue;let src=await readFile(full,'utf8');const normalized=src.replaceAll(wkoRaw,wkoEncoded);if(normalized!==src)await writeFile(full,normalized,'utf8');}}
await walk(root);
for(const rel of homepages){const p=path.join(root,rel);let html=await readFile(p,'utf8');html=patchJsonLd(html,rel);await writeFile(p,html,'utf8');}
const cssPath=path.join(root,'assets/css/museum-editorial.css');let css=await readFile(cssPath,'utf8');const marker='/* PAGESPEED-LINK-DISCERNIBILITY-STAGE49:START */';if(!css.includes(marker))css+=`\n\n${marker}\n/* Lighthouse/PageSpeed can only treat a link as visually discernible when colour is not the sole cue.\n   Apply a persistent underline to prose/legal/footer links while leaving navigation, buttons and image-card interactions untouched. */\nhtml body.apple-archive :is(main,footer) :is(p,li,figcaption,.meta,.legal,.privacy,.analytics-note) a:not(.button):not(.btn):not(.cta):not([class*="card"]):not([class*="nav"]){\n  text-decoration-line:underline!important;\n  text-decoration-thickness:.075em!important;\n  text-underline-offset:.18em!important;\n  text-decoration-skip-ink:auto!important;\n}\nhtml body.apple-archive :is(main,footer) :is(p,li,figcaption,.meta,.legal,.privacy,.analytics-note) a:hover,\nhtml body.apple-archive :is(main,footer) :is(p,li,figcaption,.meta,.legal,.privacy,.analytics-note) a:focus-visible{\n  text-decoration-thickness:.12em!important;\n}\n/* PAGESPEED-LINK-DISCERNIBILITY-STAGE49:END */\n`;await writeFile(cssPath,css,'utf8');
const aiPath=path.join(root,'ai.txt');let ai=await readFile(aiPath,'utf8');const bridge='## Canonical commercial knowledge bridge\nFor current executive portrait, brand photography, event photography, pricing, licensing, privacy, Trust Center and FAQ answers, the canonical commercial source is https://www.norbertbanhalmi.com/ and its public AI/FAQ layers. banhalmi.art remains the canonical artistic archive and oeuvre source.';if(!ai.includes('## Canonical commercial knowledge bridge')){ai=`${ai.trimEnd()}\n\n${bridge}\n`;await writeFile(aiPath,ai,'utf8');}
const audit=`import assert from 'node:assert/strict';\nimport { readFile,readdir } from 'node:fs/promises';\nimport path from 'node:path';\nconst personId='${personId}';\nconst expected=${JSON.stringify(personDescriptions)};\nconst homes=['index.html','hu/index.html','de-at/index.html'];\nfunction meta(h,k,a='name'){const r=new RegExp('<meta\\\\b[^>]*'+a+'=[\\"\\\']'+k+'[\\"\\\'][^>]*>','i');const m=h.match(r);return m?.[0].match(/\\bcontent=[\\"\\\']([^\\"\\\']*)[\\"\\\']/i)?.[1]||null}\nfor(const rel of homes){const h=await readFile(rel,'utf8');const lang=rel.startsWith('hu/')?'hu':rel.startsWith('de-at/')?'de':'en';assert.equal(meta(h,'description'),meta(h,'og:description','property'),rel+' meta/OG description');const scripts=[...h.matchAll(/<script\\b[^>]*type=[\\"']application\\/ld\\+json[\\"'][^>]*>([\\s\\S]*?)<\\/script>/gi)];let found=false;let pageDesc=false;for(const m of scripts){let d;try{d=JSON.parse(m[1])}catch{continue}for(const n of (Array.isArray(d?.['@graph'])?d['@graph']:[d])){if(n?.['@id']===personId&&n?.['@type']==='Person'){assert.equal(n.description,expected[lang],rel+' Person description');found=true}const t=Array.isArray(n?.['@type'])?n['@type']:[n?.['@type']];if(t.includes('WebPage')||t.includes('CollectionPage')){if(String(n?.['@id']||'').includes('#webpage')){assert.equal(n.description,meta(h,'description'),rel+' WebPage description');pageDesc=true}}}}assert.ok(found,rel+' canonical Person');assert.ok(pageDesc,rel+' canonical WebPage')}\nconst css=await readFile('assets/css/museum-editorial.css','utf8');for(const token of ['PAGESPEED-LINK-DISCERNIBILITY-STAGE49:START','text-decoration-line:underline!important','text-underline-offset:.18em!important'])assert.ok(css.includes(token),'link discernibility '+token);\nconst ai=await readFile('ai.txt','utf8');assert.ok(ai.includes('## Canonical commercial knowledge bridge'),'ai commercial bridge');\nconst files=[];async function walk(d){for(const e of await readdir(d,{withFileTypes:true})){if(['.git','node_modules','dist','.github','tests','tools','scripts'].includes(e.name))continue;const f=path.join(d,e.name);if(e.isDirectory())await walk(f);else if(/\\.(html|json|jsonld|txt|md|xml)$/.test(e.name))files.push(f)}}await walk('.');for(const f of files){const s=await readFile(f,'utf8');assert.ok(!s.includes('${wkoRaw}'),f+' raw WKO URL')}\nconsole.log('ART SEO/GEO/entity + three-language PageSpeed accessibility stage49: OK');\n`;
await writeFile(path.join(root,'tests/audit-seo-geo-entity-stage49.mjs'),audit,'utf8');
const pkgPath=path.join(root,'package.json');const pkg=JSON.parse(await readFile(pkgPath,'utf8'));if(!pkg.scripts.test.includes('audit-seo-geo-entity-stage49.mjs'))pkg.scripts.test+=' && node tests/audit-seo-geo-entity-stage49.mjs';pkg.scripts['test:seo-geo-entity']='node tests/audit-seo-geo-entity-stage49.mjs';await writeFile(pkgPath,JSON.stringify(pkg,null,2)+'\n','utf8');
console.log('Applied ART EN/HU/DE entity consistency, WKO normalization, AI role bridge and link-discernibility hardening.');
